INSERT INTO "media" ("url", "storage_key", "kind", "mime", "filename", "size", "width", "height", "alt", "caption", "credit", "folder")
SELECT '/medias/ismael-camara-brio-atletico.jpg', 'public/medias/ismael-camara-brio-atletico.jpg', 'image', 'image/jpeg', 'ismael-camara-brio-atletico.jpg', 299306, 1179, 882, 'Ismaël Camara et la Brio Youth Academy avec les joueurs de l''Atlético de Madrid après leur match', 'Ismaël Camara avec la Brio Youth Academy, face à l''Atlético de Madrid', 'Brio Youth Academy', 'brio-youth-academy'
WHERE NOT EXISTS (SELECT 1 FROM "media" WHERE "url" = '/medias/ismael-camara-brio-atletico.jpg');
