UPDATE "articles" SET
  "cover_id" = (SELECT "id" FROM "media" WHERE "url" = '/medias/ismael-camara-brio-atletico.jpg' ORDER BY "id" LIMIT 1),
  "body_html" = replace("body_html", '<h2>Le top 15 mondial des joueurs nés depuis 2007</h2>', '<figure><img src="/medias/ismael-camara-brio-atletico.jpg" alt="Ismaël Camara et la Brio Youth Academy avec les joueurs de l''Atlético de Madrid après leur match" width="1179" height="882" loading="lazy" /><figcaption><strong>Ismaël Camara</strong> (au centre, en bleu, au deuxième rang) sous le maillot de la Brio Youth Academy, lors d''un match contre l''Atlético de Madrid en 2022. Photo : Brio Youth Academy.</figcaption></figure><p>Cette photo dit beaucoup de son parcours. Bien avant la Youth League, <strong>Ismaël Camara</strong> se mesurait déjà à ce qui se fait de mieux en Europe avec la Brio Youth Academy : ici en 2022, alors qu''il n''avait pas encore 15 ans, face aux jeunes de l''<strong>Atlético de Madrid</strong>, l''un des plus grands centres de formation du continent.</p><h2>Le top 15 mondial des joueurs nés depuis 2007</h2>'),
  "en_body_html" = replace("en_body_html", '<h2>The world top 15 of players born since 2007</h2>', '<figure><img src="/medias/ismael-camara-brio-atletico.jpg" alt="Ismaël Camara and Brio Youth Academy with the Atlético de Madrid players after their match" width="1179" height="882" loading="lazy" /><figcaption><strong>Ismaël Camara</strong> (centre, in blue, second row) in Brio Youth Academy colours, during a match against Atlético de Madrid in 2022. Photo: Brio Youth Academy.</figcaption></figure><p>This picture says a lot about his journey. Long before the Youth League, <strong>Ismaël Camara</strong> was already testing himself against the best in Europe with Brio Youth Academy: here in 2022, before he had even turned 15, against the youngsters of <strong>Atlético de Madrid</strong>, one of the continent''s great academies.</p><h2>The world top 15 of players born since 2007</h2>'),
  "updated_content_at" = now()
WHERE "slug" = 'les-meilleurs-jeunes-d-europe-2007-2009-ismael-camara-le-joyau-de-lille';
